tape( 'the function handles N=1 edge case (positive values)', function test( t ) {
	var DL = new Float64Array( 0 );
	var DU = new Float64Array( 0 );
	var D = new Float64Array( [ 42.0 ] );
	var v;

	v = dlangt( 'M', 1, DL, 1, D, 1, DU, 1 );
	t.strictEqual( v, 42.0, 'returns expected value for max norm' );

	v = dlangt( '1', 1, DL, 1, D, 1, DU, 1 );
	t.strictEqual( v, 42.0, 'returns expected value for one norm' );

	v = dlangt( 'I', 1, DL, 1, D, 1, DU, 1 );
	t.strictEqual( v, 42.0, 'returns expected value for infinity norm' );

	v = dlangt( 'F', 1, DL, 1, D, 1, DU, 1 );
	t.strictEqual( v, 42.0, 'returns expected value for Frobenius norm' );

	t.end();
});

