tape( 'the function computes the Frobenius norm without intermediate overflow', function test( t ) {
	// Squaring the elements overflows, and thus an unscaled sum of squares would return `Infinity`:
	var expected = 2.6457513110645908e+300; // sqrt(7)*1.0e300
	var DL = new Float64Array( [ 1.0e300, 1.0e300 ] );
	var DU = new Float64Array( [ 1.0e300, 1.0e300 ] );
	var D = new Float64Array( [ 1.0e300, 1.0e300, 1.0e300 ] );
	var v;

	v = dlangt( 'F', 3, DL, 1, D, 1, DU, 1 );
	t.strictEqual( isAlmostSameValue( v, expected, 1 ), true, 'returns expected value' );

	t.end();
});

tape( 'the function computes the Frobenius norm without intermediate underflow', function test( t ) {
	// Squaring the elements underflows to zero, and thus an unscaled sum of squares would return `0`:
	var expected = 2.6457513110645907e-300; // sqrt(7)*1.0e-300
	var DL = new Float64Array( [ 1.0e-300, 1.0e-300 ] );
	var DU = new Float64Array( [ 1.0e-300, 1.0e-300 ] );
	var D = new Float64Array( [ 1.0e-300, 1.0e-300, 1.0e-300 ] );
	var v;

	v = dlangt( 'F', 3, DL, 1, D, 1, DU, 1 );
	t.strictEqual( isAlmostSameValue( v, expected, 1 ), true, 'returns expected value' );

	t.end();
});

tape( 'the function computes the Frobenius norm when elements span the full range of magnitudes', function test( t ) {
	var expected = 1.4142135623730952e+300; // sqrt(2)*1.0e300
	var DL = new Float64Array( [ 1.0e300, 3.0 ] );
	var DU = new Float64Array( [ 1.0e-300, 4.0 ] );
	var D = new Float64Array( [ 1.0e300, 1.0e-300, 2.0 ] );
	var v;

	v = dlangt( 'F', 3, DL, 1, D, 1, DU, 1 );
	t.strictEqual( isAlmostSameValue( v, expected, 1 ), true, 'returns expected value' );

	t.end();
});

