tape( 'the function returns NaN if any element in DL is NaN', function test( t ) {
	var DL = new Float64Array( [ 1.0, NaN, 1.0 ] );
	var DU = new Float64Array( [ 1.0, 1.0, 1.0 ] );
	var D = new Float64Array( [ 2.0, 3.0, 4.0, 5.0 ] );
	var v;

	v = dlangt( 'M', 4, DL, 1, D, 1, DU, 1 );
	t.strictEqual( isnan( v ), true, 'returns NaN' );

	v = dlangt( '1', 4, DL, 1, D, 1, DU, 1 );
	t.strictEqual( isnan( v ), true, 'returns NaN' );

	v = dlangt( 'I', 4, DL, 1, D, 1, DU, 1 );
	t.strictEqual( isnan( v ), true, 'returns NaN' );

	v = dlangt( 'F', 4, DL, 1, D, 1, DU, 1 );
	t.strictEqual( isnan( v ), true, 'returns NaN' );

	t.end();
});

